INSERT INTO workflow_task_notify_appointment_cf (id_task, sender_name, sender_email, subject, message, recipients_cc, recipients_bcc, id_action_cancel, ical_notification, create_notif, location, is_sms) VALUES
(3, 'CiteLibre - Rendez-vous', 'no-reply@citelibre.org', 'Confirmation de votre rendez-vous ${reference}', '<p>Bonjour ${firstName} ${lastName},</p><p>Votre rendez-vous du <strong>${date_appointment} à ${time_appointment}</strong> est confirmé.</p><p>Référence : <strong>${reference}</strong></p>${recap!}<p>Un empêchement ? <a href="${url_cancel}">Annulez votre rendez-vous</a> pour libérer le créneau.</p><p>À bientôt,<br/>Le service accueil</p>', '', '', 5, 0, 0, '', 0),
(4, 'CiteLibre - Rendez-vous', 'no-reply@citelibre.org', 'Merci de votre visite', '<p>Bonjour ${firstName} ${lastName},</p><p>Merci d''être venu(e) à votre rendez-vous du ${date_appointment} à ${time_appointment}.</p><p>N''hésitez pas à prendre un nouveau rendez-vous en ligne si besoin.</p><p>Le service accueil</p>', '', '', 5, 0, 0, '', 0),
(5, 'CiteLibre - Rendez-vous', 'no-reply@citelibre.org', 'Rendez-vous manqué', '<p>Bonjour ${firstName} ${lastName},</p><p>Nous ne vous avons pas vu à votre rendez-vous du ${date_appointment} à ${time_appointment} (référence ${reference}).</p><p>Vous pouvez reprendre un rendez-vous en ligne à tout moment.</p><p>Le service accueil</p>', '', '', 5, 0, 0, '', 0),
(7, 'CiteLibre - Rendez-vous', 'no-reply@citelibre.org', 'Annulation de votre rendez-vous ${reference}', '<p>Bonjour ${firstName} ${lastName},</p><p>Votre rendez-vous du ${date_appointment} à ${time_appointment} (référence ${reference}) est annulé.</p><p>Vous pouvez reprendre un rendez-vous en ligne à tout moment.</p><p>Le service accueil</p>', '', '', 5, 0, 0, '', 0);
